dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "SingleCell",
      "data point": {
        "type": "api",
        "url": "https://bioindex-dev.hugeamp.org/api/raw/file/single_cell_all_metadata/dataset_metadata.json.gz",
        "data type": "line json"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "datasetName"
          },
          {
            "type": "raw",
            "field name": "datasetId",
            "raw field": "datasetId"
          },
          {
            "type": "raw",
            "field name": "Species",
            "raw field": "species"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Total Cells",
            "raw field": "totalCells"
          },
          {
            "type": "raw",
            "field name": "Data Type",
            "raw field": "data_type"
          }
        ],
        "top rows": [
          "datasetId",
          "Name",
          "Species",
          "Tissue",
          "Total Cells"
        ],
        "select column": "datasetId",
        "show select column values": false
      },
      "pre filters": [
        {
        "field": "Data Type",
        "value": "single_cell",
        "type": "search"
        }
      ],
      "visualizer": {
        "type": "cell browser",
        "label": "Single Cell Browser",

        "bioIndex": "https://bioindex-dev.hugeamp.org",
        "format":{
          "default":{
            "displayMap":{
              "biosample_id": "Biosample ID",
              "donor_id": "Donor ID",
              "sex": "Sex",
              "disease__ontology_label": "Disease",
              "cell_type__author": "Cell Type",
              "bmi": "BMI",
              "custom__Hepatocyte.necrosis": "Hepatocyte Necrosis",
              "custom__Age": "Age (years)",
              "custom__Fat.distribution": "Fat Distribution",
              "custom__Portal.inflammation": "Portal Inflammation",
              "custom__Lobular.inflammation": "Lobular Inflammation",
              "custom__Fibrosis.stage": "Fibrosis Stage",
              "custom__batch": "Batch",
              "custom__Steatosis.grade": "Steatosis Grade",
              "custom__Ballooning": "Ballooning",
              "custom__cellsubtype": "Cell Sub-Type",
              "custom__condition": "Condition"
            }
          }
        },

        "parameters":{
          "datasetId": "datasetId",
          "gene": "gene"
        },
        "data points":[ 
          {
            "role": "metadata",
            "url": "https://bioindex-dev.hugeamp.org/api/raw/file/single_cell_all_metadata/dataset_metadata.json.gz"
          },{
            "role": "fields",
            "url": "https://bioindex-dev.hugeamp.org/api/raw/file/single_cell/$datasetId/fields.json.gz"
          },{
            "role": "coordinates",
            "url": "https://bioindex-dev.hugeamp.org/api/raw/file/single_cell/$datasetId/coordinates.tsv.gz"
          },{
            "role": "expression",
            "url": "https://bioindex-dev.hugeamp.org/api/bio/query/single-cell-lognorm?q=$datasetId,$gene"
          },{
            "role": "markers",
            "url": "https://bioindex-dev.hugeamp.org/api/raw/file/single_cell/$datasetId/marker_genes.json.gz"
          }
        ],
        "components": {
          "cell info": {
            "enabled": true
          },
          "cell proportion": {
            "enabled": true
          },
          "gene expression": {
            "enabled": true
          },
          "marker genes": {
            "enabled": true
          }
        },
        "presets": {
          "cell type label": "cell_type__author",
          "genes": []
        }
      }
    }
  ]
}
